import React, { useCallback, useEffect, useMemo, useRef, useState } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import {
  Button,
  FormActions,
  FormRowCol,
  FormSkeleton,
  Input,
  LabelMoney,
  MoneyInput,
  SearchInput,
  Select,
  dispatchAppToast,
  localInputToISOWithOffset,
} from '@linm-soft-org/linm-web-common-components';
import type { ActiveCompanyItem } from '@linm-soft-org/linm-web-common-components';
import { fpcService } from '../../../services/fpc/service';
import { useAppDispatch } from '../../../store/hooks';
import { createCompanySearchConfig } from '../../../components/search/companySearchConfig';
import type { CostCodeDto, CostPlanItemDto, PlanVoucherDraftDto } from '../../../services/fpc/types';
import styles from './PlanVoucherDemoView.module.css';

declare global {
  interface Window {
    __LINM_UPDATE_TAB_TITLE__?: (title: string) => void;
    __LINM_IS_CURRENT_TAB_DIRTY__?: boolean;
  }
}

const TEST_ID = 'plan-voucher-demo';

/* ── Processing level options ───────────── */
const PROCESSING_LEVEL_OPTIONS = [
  { value: '1', label: 'Mức 1: Nhập liệu' },
  { value: '5', label: 'Mức 5: Kiểm tra' },
  { value: '9', label: 'Mức 9: Hoạch toán' },
];

/* ── RequiredMark component ──────────────── */
const RequiredMark: React.FC = () => (
  <span className={styles.requiredMark} aria-hidden="true">*</span>
);

/* ── Format helpers ──────────────────────── */
const fVnd = (v: number): string =>
  new Intl.NumberFormat('vi-VN', { style: 'currency', currency: 'VND', maximumFractionDigits: 0 }).format(v);

const todayDateStr = () => {
  const d = new Date();
  return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}-${String(d.getDate()).padStart(2, '0')}`;
};

/* ── Types ────────────────────────────────── */
type PlanTab = 'revenue' | 'expense';
type VoucherType = 'doi-tuong' | 'cua-hang' | 'ma-chi-phi';

const VOUCHER_TYPE_OPTIONS: { value: VoucherType; label: string }[] = [
  { value: 'doi-tuong', label: 'Đối tượng' },
  { value: 'cua-hang', label: 'Cửa hàng' },
  { value: 'ma-chi-phi', label: 'Mã chi phí' },
];

const PRIORITY_OPTIONS = [
  { value: 'Critical', label: 'Rất cao' },
  { value: 'High', label: 'Cao' },
  { value: 'Medium', label: 'Trung bình' },
  { value: 'Low', label: 'Thấp' },
];

interface PlanLine {
  id: string;
  entityCode: string;
  entityName: string;
  entityGroup: string;
  plannedAmount: number;
  actualAmount: number;
  mustPay: number;
  debt: number;
  priority: string;
}

/* ── Status logic ─────────────────────────── */
function getPriorityColor(priority: string): string {
  switch (priority) {
    case 'Critical': return '#991b1b';
    case 'High': return '#d97706';
    case 'Medium': return '#2563eb';
    case 'Low': return '#6b7280';
    default: return '#6b7280';
  }
}

function getPriorityBg(priority: string): string {
  switch (priority) {
    case 'Critical': return '#fee2e2';
    case 'High': return '#fef3c7';
    case 'Medium': return '#dbeafe';
    case 'Low': return '#f3f4f6';
    default: return '#f3f4f6';
  }
}

/* ── Component ────────────────────────────── */
const PlanVoucherDemoView: React.FC = () => {
  const isDemo = true;
  const dispatch = useAppDispatch();
  const navigate = useNavigate();
  const { id } = useParams<{ id: string }>();
  const isCreate = !id || id === 'new';

  /* ── Period state ──────────────────────── */
  const now = new Date();
  const [planYear, setPlanYear] = useState(now.getFullYear());
  const [planMonth, setPlanMonth] = useState(now.getMonth() + 1);

  /* ── Voucher entity ────────────────────── */
  const [voucher, setVoucher] = useState<PlanVoucherDraftDto | null>(null);
  const [voucherLoading, setVoucherLoading] = useState(!isCreate);

  /* ── Data state ────────────────────────── */
  const [costCodes, setCostCodes] = useState<CostCodeDto[]>([]);
  const [costPlans, setCostPlans] = useState<CostPlanItemDto[]>([]);
  const [loading, setLoading] = useState(true);
  const [loadedPeriod, setLoadedPeriod] = useState({ year: 0, month: 0 });

  /* ── UI state ──────────────────────────── */
  const [activeTab, setActiveTab] = useState<PlanTab>('expense');
  const [voucherType, setVoucherType] = useState<VoucherType>('ma-chi-phi');
  const [editMode, setEditMode] = useState(true); // default edit mode
  const [saving, setSaving] = useState(false);
  const [editedLines, setEditedLines] = useState<Record<string, number>>({});
  const [editedMustPay, setEditedMustPay] = useState<Record<string, number>>({});
  const [editedNotes, setEditedNotes] = useState<Record<string, string>>({});
  const [editedPriority, setEditedPriority] = useState<Record<string, string>>({});
  const [selectedLineIndex, setSelectedLineIndex] = useState(-1);

  /* ── Processing level ──────────────────── */
  const [processingLevel, setProcessingLevel] = useState('1');

  /* ── Local add/delete state ────────────── */
  const [localAddedLines, setLocalAddedLines] = useState<PlanLine[]>([]);
  const [localDeletedIds, setLocalDeletedIds] = useState<Set<string>>(new Set());
  const localIdCounter = useRef(0);

  /* ── Voucher header state ──────────────── */
  const [voucherCode, setVoucherCode] = useState(isCreate
    ? `PKH-${now.getFullYear()}${String(now.getMonth() + 1).padStart(2, '0')}-${String(now.getDate()).padStart(2, '0')}-0001`
    : '');
  const [voucherDate, setVoucherDate] = useState(todayDateStr());
  const [description, setDescription] = useState('');

  /* ── Branch filter state ───────────────── */
  const [branchCode, setBranchCode] = useState('');
  const [selectedCompany, setSelectedCompany] = useState<ActiveCompanyItem | null>(null);

  /* ── Header compact state ──────────────── */
  const [headerExpanded, setHeaderExpanded] = useState(true);

  /* ── Load voucher (edit mode) ──────────── */
  useEffect(() => {
    if (!isCreate && id && id !== 'new') {
      setVoucherLoading(true);
      fpcService.getPlanVoucherById(id)
        .then(v => {
          setVoucher(v);
          setVoucherCode(v.code);
          setVoucherDate(v.voucherDate.substring(0, 10));
          setPlanYear(v.planYear);
          setPlanMonth(v.planMonth);
          setDescription(v.description || '');
          setBranchCode(v.branchCode);
        })
        .catch(() => {
          dispatchAppToast(dispatch, { message: 'Không tìm thấy phiếu kế hoạch', type: 'error' });
        })
        .finally(() => setVoucherLoading(false));
    }
  }, [id, isCreate, dispatch]);

  /* ── Tab title sync + dirty flag ────────── */
  const tabTitle = isDemo
    ? 'Phiếu kế hoạch (Demo)'
    : isCreate
      ? 'Tạo phiếu kế hoạch'
      : `Phiếu ${voucherCode}`;

  useEffect(() => {
    if (voucherCode && typeof window.__LINM_UPDATE_TAB_TITLE__ === 'function') {
      window.__LINM_UPDATE_TAB_TITLE__(tabTitle);
    }
  }, [tabTitle, voucherCode]);

  useEffect(() => {
    window.__LINM_IS_CURRENT_TAB_DIRTY__ = editMode;
    return () => { window.__LINM_IS_CURRENT_TAB_DIRTY__ = false; };
  }, [editMode]);

  /* ── Search configs ────────────────────── */
  const companySearchConfig = useMemo(() => createCompanySearchConfig(), []);

  const objectSearchConfig = useMemo(() => {
    // Static lookup for Đối tượng — load from company list (default to tenant companies)
    return createCompanySearchConfig();
  }, []);

  /* ── Demo data generator ────────────────── */
  const generateDemoData = useCallback((year: number, month: number, vType?: VoucherType) => {
    const vt = vType || voucherType;
    const nowD = new Date();

    // ── Build entity list matching voucherType ──
    type Entity = { id: string; code: string; name: string; groupName: string; costType: 'Income' | 'Expense'; priority: string };
    let incomeEntities: Entity[];
    let expenseEntities: Entity[];

    if (vt === 'doi-tuong') {
      incomeEntities = [
        { id: 'demo-doituong-1', code: 'KH001', name: 'Công ty TNHH Thương mại Sài Gòn', groupName: 'Khách hàng doanh nghiệp', costType: 'Income', priority: 'High' },
        { id: 'demo-doituong-2', code: 'KH002', name: 'Cửa hàng Bách Hóa Xanh Q.3', groupName: 'Khách hàng bán lẻ', costType: 'Income', priority: 'Medium' },
        { id: 'demo-doituong-3', code: 'KH003', name: 'Nhà hàng Hải Sản Biển Đông', groupName: 'Khách hàng F&B', costType: 'Income', priority: 'Medium' },
        { id: 'demo-doituong-4', code: 'KH004', name: 'VPĐD Công ty Nước Ngoài', groupName: 'Khách hàng doanh nghiệp', costType: 'Income', priority: 'Low' },
        { id: 'demo-doituong-5', code: 'KH005', name: 'Hộ kinh doanh cá thể Nguyễn Văn A', groupName: 'Khách hàng bán lẻ', costType: 'Income', priority: 'Low' },
      ];
      expenseEntities = [
        { id: 'demo-doituong-6', code: 'NCC001', name: 'Công ty TNHH Dịch vụ Văn phòng ABC', groupName: 'Nhà cung cấp dịch vụ', costType: 'Expense', priority: 'High' },
        { id: 'demo-doituong-7', code: 'NCC002', name: 'Công ty Điện lực Thành phố', groupName: 'Nhà cung cấp tiện ích', costType: 'Expense', priority: 'High' },
        { id: 'demo-doituong-8', code: 'NCC003', name: 'Công ty Cho thuê Văn phòng Sài Gòn', groupName: 'Nhà cung cấp bất động sản', costType: 'Expense', priority: 'High' },
        { id: 'demo-doituong-9', code: 'NCC004', name: 'Công ty TNHH Vận tải Nhanh 24/7', groupName: 'Nhà cung cấp logistics', costType: 'Expense', priority: 'Medium' },
        { id: 'demo-doituong-10', code: 'NCC005', name: 'Đại lý Thuế và Kế toán An Phát', groupName: 'Nhà cung cấp dịch vụ', costType: 'Expense', priority: 'Medium' },
        { id: 'demo-doituong-11', code: 'NCC006', name: 'Công ty TNHH Quảng cáo Truyền thông SG', groupName: 'Nhà cung cấp marketing', costType: 'Expense', priority: 'Medium' },
        { id: 'demo-doituong-12', code: 'NCC007', name: 'Công ty Bảo hiểm Bảo Việt', groupName: 'Nhà cung cấp bảo hiểm', costType: 'Expense', priority: 'Medium' },
        { id: 'demo-doituong-13', code: 'NCC008', name: 'Công ty TNHH Dịch vụ Vệ sinh Xanh', groupName: 'Nhà cung cấp dịch vụ', costType: 'Expense', priority: 'Low' },
      ];
    } else if (vt === 'cua-hang') {
      incomeEntities = [
        { id: 'demo-cuahang-1', code: 'CH001', name: 'Cửa hàng Số 1 — Nguyễn Huệ', groupName: 'Khu vực Trung tâm', costType: 'Income', priority: 'High' },
        { id: 'demo-cuahang-2', code: 'CH002', name: 'Cửa hàng Số 2 — Lê Lợi', groupName: 'Khu vực Trung tâm', costType: 'Income', priority: 'Medium' },
        { id: 'demo-cuahang-3', code: 'CH003', name: 'Cửa hàng Số 3 — Phạm Ngũ Lão', groupName: 'Khu vực Quận 1', costType: 'Income', priority: 'Medium' },
        { id: 'demo-cuahang-4', code: 'CH004', name: 'Cửa hàng Số 4 — Tân Bình', groupName: 'Khu vực Nội thành', costType: 'Income', priority: 'Low' },
        { id: 'demo-cuahang-5', code: 'CH005', name: 'Cửa hàng Số 5 — Gò Vấp', groupName: 'Khu vực Nội thành', costType: 'Income', priority: 'Low' },
      ];
      expenseEntities = [
        { id: 'demo-cuahang-6', code: 'CH006', name: 'Cửa hàng Số 6 — Thủ Đức', groupName: 'Khu vực Ngoại thành', costType: 'Expense', priority: 'Medium' },
        { id: 'demo-cuahang-7', code: 'CH007', name: 'Cửa hàng Số 7 — Bình Thạnh', groupName: 'Khu vực Nội thành', costType: 'Expense', priority: 'Medium' },
        { id: 'demo-cuahang-8', code: 'CH008', name: 'Cửa hàng Số 8 — Quận 7', groupName: 'Khu vực Nam Sài Gòn', costType: 'Expense', priority: 'Medium' },
        { id: 'demo-cuahang-9', code: 'CH009', name: 'Cửa hàng Số 9 — Tân Phú', groupName: 'Khu vực Nội thành', costType: 'Expense', priority: 'Low' },
        { id: 'demo-cuahang-10', code: 'CH010', name: 'Cửa hàng Số 10 — Hóc Môn', groupName: 'Khu vực Ngoại thành', costType: 'Expense', priority: 'Low' },
        { id: 'demo-cuahang-11', code: 'CH011', name: 'Cửa hàng Số 11 — Bình Tân', groupName: 'Khu vực Nội thành', costType: 'Expense', priority: 'Low' },
      ];
    } else {
      // ma-chi-phi (default — cost codes)
      incomeEntities = [
        { id: 'demo-income-1', code: 'DT-BH', name: 'Bán hàng trực tiếp', groupName: 'Doanh thu bán hàng', costType: 'Income', priority: 'High' },
        { id: 'demo-income-2', code: 'DT-OL', name: 'Bán hàng online', groupName: 'Doanh thu bán hàng', costType: 'Income', priority: 'Medium' },
        { id: 'demo-income-3', code: 'DT-MB', name: 'Phí membership', groupName: 'Doanh thu định kỳ', costType: 'Income', priority: 'Low' },
        { id: 'demo-income-4', code: 'DT-KH', name: 'Thu khác', groupName: 'Doanh thu khác', costType: 'Income', priority: 'Low' },
      ];
      expenseEntities = [
        { id: 'demo-expense-1', code: 'CP-NV', name: 'Lương nhân viên', groupName: 'Chi phí nhân sự', costType: 'Expense', priority: 'High' },
        { id: 'demo-expense-2', code: 'CP-MB', name: 'Tiền thuê mặt bằng', groupName: 'Chi phí cố định', costType: 'Expense', priority: 'High' },
        { id: 'demo-expense-3', code: 'CP-DN', name: 'Điện nước và dịch vụ', groupName: 'Chi phí vận hành', costType: 'Expense', priority: 'Medium' },
        { id: 'demo-expense-4', code: 'CP-VC', name: 'Vận chuyển và hậu cần', groupName: 'Chi phí vận hành', costType: 'Expense', priority: 'Medium' },
        { id: 'demo-expense-5', code: 'CP-TM', name: 'Tiếp thị và quảng cáo', groupName: 'Chi phí bán hàng', costType: 'Expense', priority: 'Medium' },
        { id: 'demo-expense-6', code: 'CP-TH', name: 'Thuế và phí', groupName: 'Chi phí bắt buộc', costType: 'Expense', priority: 'High' },
        { id: 'demo-expense-7', code: 'CP-BH', name: 'Bảo hiểm', groupName: 'Chi phí nhân sự', costType: 'Expense', priority: 'Medium' },
        { id: 'demo-expense-8', code: 'CP-KH', name: 'Chi phí khác', groupName: 'Chi phí vận hành', costType: 'Expense', priority: 'Low' },
      ];
    }

    const allCodes: CostCodeDto[] = [...incomeEntities, ...expenseEntities].map(e => ({
      id: e.id,
      code: e.code,
      name: e.name,
      costType: e.costType,
      comparisonMethod: 'Month' as const,
      groupName: e.groupName,
      isActive: true,
      priority: e.priority,
    }));
    setCostCodes(allCodes);

    // Generate mock cost plans
    const incomeAmounts = [1_200_000_000, 380_000_000, 180_000_000, 65_000_000, 45_000_000];
    const expenseAmounts = [350_000_000, 180_000_000, 95_000_000, 120_000_000, 80_000_000, 55_000_000, 45_000_000, 30_000_000, 25_000_000, 20_000_000, 15_000_000];
    const allPlans: CostPlanItemDto[] = [];

    incomeEntities.forEach((e, i) => {
      const planned = incomeAmounts[i] || 50_000_000;
      allPlans.push({
        id: `demo-plan-${e.id}`,
        costCode: e.code,
        costCodeName: e.name,
        groupName: e.groupName || '',
        plannedAmount: planned,
        actualAmount: 0,
        mustPay: 0,
        debt: 0,
        variance: 0,
        priority: '',
        branchCode: 'HQ',
        year,
        month,
      });
    });

    expenseEntities.forEach((e, i) => {
      const planned = expenseAmounts[i] || 25_000_000;
      const mp = i < 3 ? planned : 0;
      allPlans.push({
        id: `demo-plan-${e.id}`,
        costCode: e.code,
        costCodeName: e.name,
        groupName: e.groupName || '',
        plannedAmount: planned,
        actualAmount: 0,
        mustPay: mp,
        debt: 0,
        variance: 0,
        priority: i < 2 ? 'High' : i < 5 ? 'Medium' : 'Low',
        branchCode: 'HQ',
        year,
        month,
      });
    });

    setCostPlans(allPlans);
    setLoadedPeriod({ year, month });
    setVoucherCode(`DEMO-PKH-${year}${String(month).padStart(2, '0')}-0001`);
    setDescription(`Kế hoạch tài chính demo tháng ${month}/${year}`);
    setPlanYear(year);
    setPlanMonth(month);
    setLocalAddedLines([]);
    setLocalDeletedIds(new Set());
    setEditedLines({});
    setEditedMustPay({});
    setEditedNotes({});
    setEditedPriority({});
  }, [voucherType]);

  /* ── Fetch data ────────────────────────── */
  const fetchData = useCallback(async (year: number, month: number, branch?: string) => {
    if (isDemo) {
      generateDemoData(year, month, voucherType);
      setLoading(false);
      return;
    }
    setLoading(true);
    try {
      // Mã CP SSOT = Master expense-items — không còn GET /fpc/cost-codes
      const plans = await fpcService.getCostPlanList({
        year,
        month,
        branchCode: branch || undefined,
      });
      setCostCodes([]);
      setCostPlans(plans);
      setLoadedPeriod({ year, month });
    } catch {
      dispatchAppToast(dispatch, { message: 'Không thể tải dữ liệu kế hoạch', type: 'error' });
    } finally {
      setLoading(false);
    }
  }, [dispatch, isDemo, generateDemoData]);

  useEffect(() => {
    fetchData(planYear, planMonth, branchCode);
  }, [fetchData, planYear, planMonth, branchCode]);

  /* ── Period change ─────────────────────── */
  const handlePeriodChange = (year: number, month: number) => {
    setPlanYear(year);
    setPlanMonth(month);
    setEditedLines({});
    setEditedMustPay({});
    setEditedNotes({});
    setEditedPriority({});
    setLocalAddedLines([]);
    setLocalDeletedIds(new Set());
    setVoucherCode(`KH-${year}${String(month).padStart(2, '0')}-001`);
    setDescription(`Kế hoạch tài chính tháng ${month}/${year}`);
  };

  /* ── Branch change ─────────────────────── */
  const handleBranchChange = (item: ActiveCompanyItem | null) => {
    const code = item?.code ?? item?.id ?? '';
    setBranchCode(code);
    setSelectedCompany(item);
    setEditedLines({});
    setEditedMustPay({});
    setEditedNotes({});
    setLocalAddedLines([]);
    setLocalDeletedIds(new Set());
  };

  /* ── Revenue lines ─────────────────────── */
  const revenueLines = useMemo((): PlanLine[] => {
    const incomeCodes = new Set(costCodes.filter(c => c.costType === 'Income').map(c => c.code));
    return costPlans
      .filter(p => incomeCodes.size === 0 || incomeCodes.has(p.costCode))
      .map(p => ({
        id: p.id,
        entityCode: p.costCode,
        entityName: p.costCodeName || p.costCode,
        entityGroup: p.groupName || 'Khác',
        plannedAmount: p.plannedAmount,
        actualAmount: p.actualAmount,
        mustPay: p.mustPay,
        debt: p.debt,
        priority: p.priority || '',
      }));
  }, [costPlans, costCodes]);

  /* ── Expense lines ─────────────────────── */
  const expenseLines = useMemo((): PlanLine[] => {
    const expenseCodes = new Set(costCodes.filter(c => c.costType !== 'Income').map(c => c.code));
    return costPlans
      .filter(p => expenseCodes.size === 0 || expenseCodes.has(p.costCode))
      .map(p => ({
        id: p.id,
        entityCode: p.costCode,
        entityName: p.costCodeName || p.costCode,
        entityGroup: p.groupName || 'Khác',
        plannedAmount: p.plannedAmount,
        actualAmount: p.actualAmount,
        mustPay: p.mustPay,
        debt: p.debt,
        priority: p.priority || '',
      }));
  }, [costPlans, costCodes]);

  /* ── Active lines ──────────────────────── */
  const sourceLines = useMemo((): PlanLine[] => {
    return activeTab === 'revenue' ? revenueLines : expenseLines;
  }, [activeTab, revenueLines, expenseLines]);

  /* ── Merged lines (server + local - deleted) ── */
  const activeLines = useMemo((): PlanLine[] => {
    const serverFiltered = sourceLines.filter(l => !localDeletedIds.has(l.id));
    return [...serverFiltered, ...localAddedLines];
  }, [sourceLines, localAddedLines, localDeletedIds]);

  /* ── Add / Copy / Remove handlers ───────── */
  const handleAddLine = useCallback(() => {
    localIdCounter.current += 1;
    const newId = `local-${localIdCounter.current}`;
    const newLine: PlanLine = {
      id: newId,
      entityCode: '',
      entityName: '',
      entityGroup: activeTab === 'revenue' ? 'Thu' : 'Chi',
      plannedAmount: 0,
      actualAmount: 0,
      mustPay: 0,
      debt: 0,
      priority: '',
    };
    setLocalAddedLines(prev => [...prev, newLine]);
    setEditedLines(prev => ({ ...prev, [newId]: 0 }));
    setEditedMustPay(prev => ({ ...prev, [newId]: 0 }));
    setEditedNotes(prev => ({ ...prev, [newId]: '' }));
    setEditedPriority(prev => ({ ...prev, [newId]: 'Medium' }));
    setSelectedLineIndex(activeLines.length);
  }, [activeTab, activeLines.length]);

  const handleCopyLine = useCallback(() => {
    if (selectedLineIndex < 0 || selectedLineIndex >= activeLines.length) return;
    const source = activeLines[selectedLineIndex];
    localIdCounter.current += 1;
    const newId = `local-${localIdCounter.current}`;
    const newLine: PlanLine = {
      ...source,
      id: newId,
    };
    setLocalAddedLines(prev => [...prev, newLine]);
    setEditedLines(prev => ({ ...prev, [newId]: source.plannedAmount }));
    setEditedMustPay(prev => ({ ...prev, [newId]: source.mustPay }));
    setEditedNotes(prev => ({ ...prev, [newId]: '' }));
    setEditedPriority(prev => ({ ...prev, [newId]: source.priority || 'Medium' }));
    setSelectedLineIndex(activeLines.length);
  }, [selectedLineIndex, activeLines]);

  const handleRemoveLine = useCallback((lineId: string) => {
    if (lineId.startsWith('local-')) {
      setLocalAddedLines(prev => prev.filter(l => l.id !== lineId));
      setEditedLines(prev => { const next = { ...prev }; delete next[lineId]; return next; });
      setEditedMustPay(prev => { const next = { ...prev }; delete next[lineId]; return next; });
      setEditedNotes(prev => { const next = { ...prev }; delete next[lineId]; return next; });
    } else {
      setLocalDeletedIds(prev => { const next = new Set(prev); next.add(lineId); return next; });
    }
    setSelectedLineIndex(-1);
  }, []);

  /* ── Per-line field edit handlers ───────── */
  /* ── Edit handlers ─────────────────────── */
  const handleEditStart = useCallback(() => {
    const init: Record<string, number> = {};
    const initMp: Record<string, number> = {};
    const initNote: Record<string, string> = {};
    activeLines.forEach(line => {
      init[line.id] = line.plannedAmount;
      initMp[line.id] = line.mustPay;
      initNote[line.id] = '';
    });
    setEditedLines(init);
    setEditedMustPay(initMp);
    setEditedNotes(initNote);
    setLocalAddedLines([]);
    setLocalDeletedIds(new Set());
    setEditMode(true);
  }, [activeLines]);

  const handleLineEdit = useCallback((id: string, value: number) => {
    setEditedLines(prev => ({ ...prev, [id]: value }));
  }, []);

  const handleMustPayEdit = useCallback((id: string, value: number) => {
    setEditedMustPay(prev => ({ ...prev, [id]: value }));
  }, []);

  const handleNoteEdit = useCallback((id: string, value: string) => {
    setEditedNotes(prev => ({ ...prev, [id]: value }));
  }, []);

  const handlePriorityEdit = useCallback((id: string, value: string) => {
    setEditedPriority(prev => ({ ...prev, [id]: value }));
  }, []);

  const handleCancel = useCallback(() => {
    setEditMode(false);
    setEditedLines({});
    setEditedMustPay({});
    setEditedNotes({});
    setLocalAddedLines([]);
    setLocalDeletedIds(new Set());
  }, []);

  const handleSave = useCallback(async () => {
    setSaving(true);

    // Demo mode: simulate save with delay
    if (isDemo) {
      await new Promise(r => setTimeout(r, 600));
      dispatchAppToast(dispatch, { message: 'Đã lưu kế hoạch (dữ liệu mô phỏng)', type: 'success' });
      setEditMode(false);
      setEditedLines({});
      setEditedMustPay({});
      setEditedNotes({});
      setLocalAddedLines([]);
      setLocalDeletedIds(new Set());
      setSaving(false);
      return;
    }

    // Real save path
    try {
      if (isCreate) {
        await fpcService.createPlanVoucher({
          voucherDate: localInputToISOWithOffset(voucherDate),
          planYear,
          planMonth,
          branchCode,
          description,
        });
      }

      const lines = activeLines
        .filter(l => (editedLines[l.id] ?? l.plannedAmount) > 0 || l.entityCode)
        .map(line => ({
          costCode: line.entityCode,
          plannedAmount: editedLines[line.id] ?? line.plannedAmount,
          mustPay: editedMustPay[line.id] ?? line.mustPay,
          note: editedNotes[line.id] ?? undefined,
        }));
      await fpcService.batchUpsertCostPlans({
        year: planYear,
        month: planMonth,
        branchCode: branchCode,
        lines,
      });
      dispatchAppToast(dispatch, { message: 'Đã lưu kế hoạch', type: 'success' });
      setEditMode(false);
      setEditedLines({});
      setEditedMustPay({});
      setEditedNotes({});
      setLocalAddedLines([]);
      setLocalDeletedIds(new Set());
      await fetchData(planYear, planMonth, branchCode);
      if (isCreate) {
        navigate('/tc/kh/ke-hoach');
      }
    } catch {
      dispatchAppToast(dispatch, { message: 'Lỗi khi lưu kế hoạch', type: 'error' });
    } finally {
      setSaving(false);
    }
  }, [dispatch, activeLines, editedLines, planYear, planMonth, branchCode, voucherDate, description, isCreate, fetchData, navigate, isDemo]);

  /* ── Print ─────────────────────────────── */
  const handlePrint = useCallback(() => {
    const el = document.getElementById('plan-voucher-content');
    if (!el) return;
    const win = window.open('', '_blank');
    if (!win) return;
    win.document.write([
      '<html><head><title>Phiếu kế hoạch</title><meta charset="utf-8"><style>',
      'body{font-family:Arial,sans-serif;padding:20px;color:#1e293b}',
      'table{width:100%;border-collapse:collapse;margin:16px 0;font-size:12px}',
      'th,td{padding:8px 12px;border:1px solid #e2e8f0;text-align:left}',
      'th{background:#f8fafc;font-weight:600;font-size:11px;text-transform:uppercase}',
      'h1{font-size:22px;color:#8b5cf6;margin:0 0 4px}',
      'h2{font-size:16px;color:#64748b;font-weight:400;margin:0 0 16px}',
      '.right{text-align:right}.money{font-family:monospace;text-align:right}',
      '.positive{color:#059669}.negative{color:#ef4444}',
      '.footer{display:flex;justify-content:flex-end;gap:24px;padding:12px;margin-top:12px}',
      '</style></head><body>',
      `<h1>Phiếu kế hoạch — ${activeTab === 'revenue' ? 'Kế hoạch thu' : 'Kế hoạch chi'} Tháng ${planMonth}/${planYear}</h1>`,
      `<h2>Ngày in: ${new Date().toLocaleString('vi-VN')}</h2>`,
      el.innerHTML,
      '</body></html>',
    ].join('\n'));
    win.document.close();
    win.print();
  }, [activeTab, planMonth, planYear]);

  /* ── Computed totals ───────────────────── */
  const totalPlanned = activeLines.reduce((s, l) => s + (editMode ? (editedLines[l.id] ?? l.plannedAmount) : l.plannedAmount), 0);
  const totalMustPay = activeLines.reduce((s, l) => s + l.mustPay, 0);
  const activeCount = activeLines.filter(l => (editMode ? (editedLines[l.id] ?? l.plannedAmount) : l.plannedAmount) > 0).length;

  const dateLabel = `Tháng ${planMonth}/${planYear}`;
  const periodMatch = loadedPeriod.year === planYear && loadedPeriod.month === planMonth;

  /* ── Render ────────────────────────────── */
  return (
    <div className={styles.page} data-form-page data-voucher-form-shell data-testid={`${TEST_ID}-page`}>
      {/* ── Toolbar header ── */}
      <div className={styles.pageFormHeader}>
        <div className={styles.stickyTop}>
          <div className={styles.pageHeader}>
            <div className={styles.titleGroup}>
              <button className={styles.backBtn} onClick={() => navigate('/demo/fpc')} type="button">
                <i className="fas fa-arrow-left" />
              </button>
              <div className={styles.titleRow}>
                <h1 className={styles.title}>
                  {isDemo ? 'Phiếu kế hoạch (Demo)' : (isCreate ? 'Tạo phiếu kế hoạch' : (voucher ? `Phiếu ${voucher.code}` : 'Phiếu kế hoạch'))}
                  {isDemo && (
                    <span style={{
                      marginLeft: 10,
                      padding: '2px 8px',
                      fontSize: 11,
                      fontWeight: 600,
                      borderRadius: 4,
                      background: '#fef3c7',
                      color: '#92400e',
                      verticalAlign: 'middle',
                    }}>
                      DỮ LIỆU MÔ PHỎNG
                    </span>
                  )}
                </h1>
              </div>
            </div>
            <FormActions align="end">
              {editMode ? (
                <>
                  <Button onClick={handleCancel} data-testid={`${TEST_ID}-cancel-btn`}>
                    <i className="fas fa-times" /> Hủy
                  </Button>
                  <Button variant="primary" onClick={handleSave} disabled={saving} data-testid={`${TEST_ID}-save-btn`}>
                    <i className={`fas ${saving ? 'fa-spinner fa-spin' : 'fa-save'}`} />
                    {saving ? ' Đang lưu...' : ' Lưu'}
                  </Button>
                </>
              ) : (
                <>
                  {isDemo && (
                    <Button variant="secondary" onClick={() => { generateDemoData(planYear, planMonth); setEditMode(false); }} data-testid={`${TEST_ID}-gen-demo-btn`}>
                      <i className="fas fa-random" /> Tạo dữ liệu mẫu
                    </Button>
                  )}
                  <Button variant="primary" onClick={handleEditStart} data-testid={`${TEST_ID}-edit-btn`}>
                    <i className="fas fa-edit" /> Sửa
                  </Button>
                  <Button onClick={handlePrint} data-testid={`${TEST_ID}-print-btn`}>
                    <i className="fas fa-print" /> In
                  </Button>
                  <Button onClick={() => fetchData(planYear, planMonth, branchCode)} data-testid={`${TEST_ID}-refresh-btn`}>
                    <i className="fas fa-redo" /> Làm mới
                  </Button>
                </>
              )}
            </FormActions>
          </div>
          {/* ── Mode hint (below toolbar) ── */}
          {isDemo && !editMode && (
            <div className={styles.viewModeHint} data-testid={`${TEST_ID}-demo-hint`} style={{ background: '#fef3c7', border: '1px solid #fde68a' }}>
              <i className="fas fa-flask" /> Dữ liệu mô phỏng — nhấn <strong>Tạo dữ liệu mẫu</strong> để tạo mới hoặc <strong>Sửa</strong> để chỉnh sửa
            </div>
          )}
          {!isCreate && !editMode && !isDemo && (
            <div className={styles.viewModeHint} data-testid={`${TEST_ID}-view-hint`}>
              <i className="fas fa-eye" /> Chế độ xem — nhấn <strong>Sửa</strong> để chỉnh sửa
            </div>
          )}
          {editMode && (
            <div className={styles.readOnlyHint} data-testid={`${TEST_ID}-edit-hint`}>
              <i className="fas fa-pen" /> Đang {isCreate ? 'tạo mới' : 'chỉnh sửa'} — Lưu hoặc Hủy
            </div>
          )}
        </div>
      </div>

      {/* ── Scrollable content ── */}
      <div className={`${styles.pageFormScroll}${!editMode ? ` ${styles.viewDisabled}` : ''}`} id="plan-voucher-content">
        {/* ── Voucher loading ── */}
        {voucherLoading && (
          <FormSkeleton headerRows={2} lineRows={3} data-testid={`${TEST_ID}-form-skeleton`} />
        )}

        {!voucherLoading && <>
          {/* ── Header section with compact toggle ── */}
          <div
            className={styles.section}
            data-testid={`${TEST_ID}-section-header`}
          >
            <div className={styles.sectionTitleRow}>
              <h2 className={styles.sectionTitle}>Thông tin phiếu kế hoạch</h2>
              <div style={{ display: 'flex', alignItems: 'center', gap: 8 }}>
                <span className={styles.sectionBadge}>{dateLabel}</span>
                <button
                  type="button"
                  className={styles.headerToggleBtn}
                  data-testid={`${TEST_ID}-header-${headerExpanded ? 'collapse' : 'expand'}`}
                  aria-expanded={headerExpanded}
                  onClick={() => setHeaderExpanded(v => !v)}
                >
                  <span className={styles.headerToggleIcon} aria-hidden>
                    <i className={headerExpanded ? 'fas fa-chevron-up' : 'fas fa-chevron-down'} />
                  </span>
                  {headerExpanded ? 'Thu gọn' : 'Mở rộng'}
                </button>
              </div>
            </div>

            {/* Row A: Labels — 5-col */}
            <FormRowCol cols={4} rowsBySize={{ large: [5], medium: [3, 2], small: [2, 1, 1, 1] }} data-testid={`${TEST_ID}-header-labels`}>
              <FormRowCol.Item>
                <label className={styles.label}>
                  Ngày lập<RequiredMark />
                </label>
              </FormRowCol.Item>
              <FormRowCol.Item>
                <label className={styles.label}>
                  Loại chứng từ<RequiredMark />
                </label>
              </FormRowCol.Item>
              <FormRowCol.Item hidden={!headerExpanded}>
                <label className={styles.label}>Số phiếu</label>
              </FormRowCol.Item>
              <FormRowCol.Item>
                <label className={styles.label}>
                  Tháng<RequiredMark />
                </label>
              </FormRowCol.Item>
              <FormRowCol.Item>
                <label className={styles.label}>
                  Năm<RequiredMark />
                </label>
              </FormRowCol.Item>
            </FormRowCol>

            {/* Row B: Inputs — 5-col */}
            <FormRowCol cols={4} rowsBySize={{ large: [5], medium: [3, 2], small: [2, 1, 1, 1] }} data-testid={`${TEST_ID}-header-inputs`}>
              <FormRowCol.Item variant="field">
                <Input
                  type="date"
                  value={voucherDate}
                  onChange={e => setVoucherDate(e.target.value)}
                  max={todayDateStr()}
                  data-testid={`${TEST_ID}-voucherDate`}
                />
              </FormRowCol.Item>
              <FormRowCol.Item variant="field">
                <Select
                  value={voucherType}
                  onChange={(e: React.ChangeEvent<HTMLSelectElement>) => setVoucherType(e.target.value as VoucherType)}
                  options={VOUCHER_TYPE_OPTIONS}
                  data-testid={`${TEST_ID}-voucherType`}
                />
              </FormRowCol.Item>
              <FormRowCol.Item variant="field" hidden={!headerExpanded}>
                <Input
                  value={voucherCode}
                  onChange={e => setVoucherCode(e.target.value)}
                  placeholder="PKH-YYYYMMDD-NNNN"
                  readOnly={!isCreate}
                  data-testid={`${TEST_ID}-voucherCode`}
                />
              </FormRowCol.Item>
              <FormRowCol.Item variant="field">
                <Select
                  value={planMonth}
                  onChange={(e: React.ChangeEvent<HTMLSelectElement>) => handlePeriodChange(planYear, parseInt(e.target.value))}
                  options={Array.from({ length: 12 }, (_, i) => ({ value: i + 1, label: `Tháng ${i + 1}` }))}
                  data-testid={`${TEST_ID}-planMonth`}
                />
              </FormRowCol.Item>
              <FormRowCol.Item variant="field">
                <Input
                  type="number"
                  value={String(planYear)}
                  onChange={e => handlePeriodChange(parseInt(e.target.value) || now.getFullYear(), planMonth)}
                  data-testid={`${TEST_ID}-planYear`}
                />
              </FormRowCol.Item>
            </FormRowCol>

            {/* Row 2: 5-col merged — Chi nhánh 2fr + Diễn giải 3fr */}
            <div className={styles.mixedRow} data-testid={`${TEST_ID}-header-branch-desc`}>
              <div className={styles.mixedItem}>
                <label className={styles.label}>Chi nhánh / Đơn vị</label>
                <SearchInput
                  config={companySearchConfig}
                  value={branchCode}
                  primaryDisplay={selectedCompany?.code}
                  secondaryDisplay={selectedCompany?.name}
                  onChange={(item) => handleBranchChange(item as ActiveCompanyItem)}
                  onClear={() => handleBranchChange(null)}
                  showLabel={false}
                  placeholder="Tất cả chi nhánh..."
                  data-testid={`${TEST_ID}-branch`}
                />
              </div>
              {headerExpanded && (
                <div className={styles.mixedItem}>
                  <label className={styles.label}>Diễn giải</label>
                  <Input
                    value={description}
                    onChange={e => setDescription(e.target.value)}
                    placeholder="Nhập mô tả kế hoạch"
                    data-testid={`${TEST_ID}-description`}
                  />
                </div>
              )}
            </div>
          </div>

          {/* ── Loading ── */}
          {loading && (
            <FormSkeleton headerRows={1} lineRows={4} showFooter={false} data-testid={`${TEST_ID}-data-skeleton`} />
          )}

          {!loading && !periodMatch && (
            <div style={{ textAlign: 'center', padding: 32, color: '#94a3b8' }}>
              <i className="fas fa-sync" style={{ fontSize: 24, display: 'block', marginBottom: 8 }} />
              Đang tải kỳ {dateLabel}...
            </div>
          )}

          {!loading && periodMatch && (
            <>
              <div className={`${styles.section} ${styles.tabContentSection}`} style={{ padding: 0 }}>
                <div className={styles.tabBar}>
                  <button
                    className={`${styles.tabBtn} ${activeTab === 'revenue' ? styles.tabActiveRevenue : ''}`}
                    onClick={() => { setActiveTab('revenue'); setLocalAddedLines([]); setLocalDeletedIds(new Set()); }}
                    type="button"
                  >
                    <i className="fas fa-arrow-up" style={{ marginRight: 6 }} />
                    Kế hoạch thu
                  </button>
                  <button
                    className={`${styles.tabBtn} ${activeTab === 'expense' ? styles.tabActiveExpense : ''}`}
                    onClick={() => { setActiveTab('expense'); setLocalAddedLines([]); setLocalDeletedIds(new Set()); }}
                    type="button"
                  >
                    <i className="fas fa-arrow-down" style={{ marginRight: 6 }} />
                    Kế hoạch chi
                  </button>
                </div>

                <div className={styles.tabContentBody}>
                  {/* Empty state */}
                  {activeLines.length === 0 && (
                    <div style={{ padding: '32px 0', textAlign: 'center', color: '#94a3b8' }}>
                      <i className="fas fa-inbox" style={{ fontSize: 32, display: 'block', marginBottom: 12 }} />
                      {branchCode
                        ? `Chưa có dữ liệu cho ${activeTab === 'revenue' ? 'kế hoạch thu' : 'kế hoạch chi'} kỳ ${dateLabel} tại chi nhánh đã chọn. `
                        : `Chưa có dữ liệu cho ${activeTab === 'revenue' ? 'kế hoạch thu' : 'kế hoạch chi'} kỳ ${dateLabel}. `}
                      Nhấn <strong>"Thêm dòng"</strong> để khai báo.
                    </div>
                  )}

                  {activeLines.length > 0 && (
                    <>
                      {/* Lines table */}
                      <div className={styles.tableWrapper}>
                        <table className={styles.linesTable}>
                          <thead>
                            <tr>
                              <th style={{ width: 36 }}>STT</th>
                              <th style={{ width: voucherType === 'ma-chi-phi' ? 100 : 120 }}>
                                {voucherType === 'doi-tuong' ? 'Mã ĐT' : voucherType === 'cua-hang' ? 'Mã CH' : 'Mã CP'}
                              </th>
                              <th>
                                {voucherType === 'doi-tuong' ? 'Tên đối tượng' : voucherType === 'cua-hang' ? 'Tên cửa hàng' : (activeTab === 'revenue' ? 'Khoản thu' : 'Khoản chi')}
                              </th>
                              {editMode && <th style={{ width: 100 }}>Ưu tiên</th>}
                              {editMode ? activeTab === 'revenue' ? (
                                <>
                                  <th className={styles.colRight} style={{ width: 160 }}>Kế hoạch thu</th>
                                  <th style={{ width: 140 }}>Ghi chú</th>
                                  <th style={{ width: 40 }} />
                                </>
                              ) : (
                                <>
                                  <th className={styles.colRight} style={{ width: 160 }}>Kế hoạch chi</th>
                                  <th className={styles.colRight} style={{ width: 160 }}>Phải chi</th>
                                  <th style={{ width: 140 }}>Ghi chú</th>
                                  <th style={{ width: 40 }} />
                                </>
                              ) : activeTab === 'revenue' ? (
                                <>
                                  <th className={styles.colRight} style={{ width: 160 }}>Dự kiến thu</th>
                                </>
                              ) : (
                                <>
                                  <th className={styles.colRight} style={{ width: 140 }}>Phải chi</th>
                                  <th className={styles.colRight} style={{ width: 140 }}>Dự chi</th>
                                </>
                              )}
                            </tr>
                          </thead>
                          <tbody>
                            {activeLines.map((line, idx) => {
                              const globalIdx = idx;
                              const isSelected = selectedLineIndex === globalIdx;
                              const isLocal = line.id.startsWith('local-');
                              const rowClass = [
                                styles.lineRow,
                                isSelected ? styles.lineRowSelected : '',
                              ].filter(Boolean).join(' ');

                              return (
                                <tr
                                  key={line.id}
                                  className={rowClass}
                                  data-testid={`${TEST_ID}-line-${globalIdx}`}
                                  onClick={() => setSelectedLineIndex(globalIdx)}
                                >
                                  <td style={{ textAlign: 'center', color: '#94a3b8', fontWeight: 500 }}>{globalIdx + 1}</td>
                                  {/* Entity lookup — SearchInput for đối tượng / cửa hàng, Input for mã CP */}
                                  <td style={{ fontWeight: 500, color: '#1e293b', fontSize: 12 }}>
                                    {editMode && isLocal ? voucherType === 'ma-chi-phi' ? (
                                      <Input
                                        className={styles.lineInput}
                                        value={line.entityCode}
                                        onChange={(e) => {
                                          setLocalAddedLines(prev => prev.map(l =>
                                            l.id === line.id ? { ...l, entityCode: e.target.value } : l
                                          ));
                                        }}
                                        placeholder="Nhập mã CP..."
                                        style={{ textAlign: 'left', fontFamily: 'inherit' }}
                                      />
                                    ) : (
                                      <SearchInput
                                        config={voucherType === 'doi-tuong' ? objectSearchConfig : companySearchConfig}
                                        value={line.entityCode}
                                        primaryDisplay={line.entityCode}
                                        secondaryDisplay={line.entityName}
                                        onChange={(item) => {
                                          const it = item as ActiveCompanyItem;
                                          setLocalAddedLines(prev => prev.map(l =>
                                            l.id === line.id ? { ...l, entityCode: it.code ?? it.id, entityName: it.name } : l
                                          ));
                                        }}
                                        onClear={() => {
                                          setLocalAddedLines(prev => prev.map(l =>
                                            l.id === line.id ? { ...l, entityCode: '', entityName: '' } : l
                                          ));
                                        }}
                                        showLabel={false}
                                        placeholder={voucherType === 'doi-tuong' ? 'Chọn đối tượng...' : 'Chọn cửa hàng...'}
                                      />
                                    ) : (
                                      line.entityCode
                                    )}
                                  </td>
                                  {/* Entity name */}
                                  <td style={{ color: '#475569' }}>
                                    {line.entityName || <span style={{ color: '#94a3b8' }}>—</span>}
                                    {!editMode && line.priority && (
                                      <span style={{
                                        marginLeft: 8,
                                        padding: '1px 6px',
                                        borderRadius: 4,
                                        fontSize: 10,
                                        fontWeight: 600,
                                        background: getPriorityBg(line.priority),
                                        color: getPriorityColor(line.priority),
                                      }}>
                                        {PRIORITY_OPTIONS.find(o => o.value === line.priority)?.label || line.priority}
                                      </span>
                                    )}
                                  </td>
                                  {/* Ưu tiên */}
                                  <td style={{ fontSize: 12 }}>
                                    {editMode ? (
                                      <select
                                        className={styles.prioritySelect}
                                        value={editedPriority[line.id] ?? (line.priority || 'Medium')}
                                        onChange={e => handlePriorityEdit(line.id, e.target.value)}
                                        data-testid={`${TEST_ID}-priority-${globalIdx}`}
                                      >
                                        {PRIORITY_OPTIONS.map(opt => (
                                          <option key={opt.value} value={opt.value}>{opt.label}</option>
                                        ))}
                                      </select>
                                    ) : line.priority ? (
                                      <span style={{
                                        padding: '1px 6px',
                                        borderRadius: 4,
                                        fontSize: 10,
                                        fontWeight: 600,
                                        background: getPriorityBg(line.priority),
                                        color: getPriorityColor(line.priority),
                                      }}>
                                        {PRIORITY_OPTIONS.find(o => o.value === line.priority)?.label || line.priority}
                                      </span>
                                    ) : (
                                      <span style={{ color: '#94a3b8' }}>—</span>
                                    )}
                                  </td>
                                  {editMode ? activeTab === 'revenue' ? (
                                    <>
                                      {/* Kế hoạch thu */}
                                          <td>
                                            <MoneyInput
                                              className={styles.lineInput}
                                              value={editedLines[line.id] ?? line.plannedAmount}
                                              onChange={v => handleLineEdit(line.id, v)}
                                            />
                                          </td>
                                          {/* Ghi chú */}
                                          <td>
                                            <Input
                                              className={`${styles.lineInput} ${styles.lineInputNote}`}
                                              value={editedNotes[line.id] ?? ''}
                                              onChange={e => handleNoteEdit(line.id, e.target.value)}
                                              placeholder="Nhập ghi chú..."
                                            />
                                          </td>
                                          {/* Xóa */}
                                          <td className={styles.tdDel}>
                                            <button
                                              type="button"
                                              className={styles.btnDeleteLine}
                                              onClick={e => { e.stopPropagation(); handleRemoveLine(line.id); }}
                                              title="Xóa dòng"
                                              data-testid={`${TEST_ID}-line-${globalIdx}-delete`}
                                            >
                                              <i className="fas fa-trash-alt" />
                                            </button>
                                          </td>
                                        </>
                                      ) : (
                                        <>
                                          {/* Kế hoạch chi */}
                                          <td>
                                            <MoneyInput
                                              className={styles.lineInput}
                                              value={editedLines[line.id] ?? line.plannedAmount}
                                              onChange={v => handleLineEdit(line.id, v)}
                                            />
                                          </td>
                                          {/* Phải chi */}
                                          <td>
                                            <MoneyInput
                                              className={styles.lineInput}
                                              value={editedMustPay[line.id] ?? line.mustPay}
                                              onChange={v => handleMustPayEdit(line.id, v)}
                                            />
                                          </td>
                                          {/* Ghi chú */}
                                          <td>
                                            <Input
                                              className={`${styles.lineInput} ${styles.lineInputNote}`}
                                              value={editedNotes[line.id] ?? ''}
                                              onChange={e => handleNoteEdit(line.id, e.target.value)}
                                              placeholder="Nhập ghi chú..."
                                            />
                                          </td>
                                          {/* Xóa */}
                                          <td className={styles.tdDel}>
                                            <button
                                              type="button"
                                              className={styles.btnDeleteLine}
                                              onClick={e => { e.stopPropagation(); handleRemoveLine(line.id); }}
                                              title="Xóa dòng"
                                              data-testid={`${TEST_ID}-line-${globalIdx}-delete`}
                                            >
                                              <i className="fas fa-trash-alt" />
                                            </button>
                                          </td>
                                        </>
                                      ) : activeTab === 'revenue' ? (
                                        <>
                                          <td className={styles.colAmount}>{fVnd(line.plannedAmount)}</td>
                                        </>
                                      ) : (
                                        <>
                                          <td className={styles.colAmount}>{fVnd(line.mustPay)}</td>
                                          <td className={styles.colAmount}>{fVnd(line.plannedAmount)}</td>
                                        </>
                                      )}
                                    </tr>
                                  );
                              })}
                          </tbody>
                        </table>
                      </div>

                      {/* Add / Copy row buttons (edit mode) */}
                      {editMode && (
                        <div className={styles.linesActions}>
                          <button
                            type="button"
                            className={styles.btnAddLine}
                            data-testid={`${TEST_ID}-add-line-btn`}
                            onClick={handleAddLine}
                          >
                            <i className="fas fa-plus" style={{ marginRight: 6 }} />
                            Thêm dòng
                          </button>
                          <button
                            type="button"
                            className={styles.btnCopyLine}
                            data-testid={`${TEST_ID}-copy-line-btn`}
                            onClick={handleCopyLine}
                            disabled={selectedLineIndex < 0}
                          >
                            <i className="fas fa-copy" style={{ marginRight: 6 }} />
                            Sao chép dòng
                          </button>
                        </div>
                      )}
                    </>
                  )}
                </div>
              </div>
            </>
          )}
        </>}
      </div>

      {/* ── Footer ── */}
      {!voucherLoading && activeCount > 0 && (
        <div className={styles.pageFormFooter}>
          <div className={styles.footer}>
            <div className={styles.footerLeft}>
              <label className={styles.footerLabel}>Mức xử lý</label>
              <Select
                className={styles.footerSelect}
                value={processingLevel}
                onChange={(e: React.ChangeEvent<HTMLSelectElement>) => setProcessingLevel(e.target.value)}
                options={PROCESSING_LEVEL_OPTIONS}
                disabled={!editMode}
                data-testid={`${TEST_ID}-processingLevel`}
              />
              <span className={styles.footerTypeLabel} style={{
                color: activeTab === 'revenue' ? '#059669' : '#ef4444',
                fontWeight: 600,
                fontSize: 14,
                padding: '4px 10px',
                borderRadius: 4,
                background: activeTab === 'revenue' ? '#d1fae5' : '#fee2e2',
              }}>
                {activeTab === 'revenue' ? 'Kế hoạch thu' : 'Kế hoạch chi'}
              </span>
              <span style={{ fontSize: 13, color: '#64748b' }}>
                {editMode ? `Đang chỉnh sửa · ${activeCount} dòng` : `${activeCount} dòng`}
              </span>
            </div>
            <div className={styles.totalBlock}>
              {activeTab === 'expense' && (
                <LabelMoney
                  label="Phải chi:"
                  value={totalMustPay}
                  variant="footer"
                  data-testid={`${TEST_ID}-footer-totalMustPay`}
                />
              )}
              <LabelMoney
                label={activeTab === 'revenue' ? 'Dự kiến thu:' : 'Kế hoạch chi:'}
                value={totalPlanned}
                variant="footer"
                emphasize
                data-testid={`${TEST_ID}-footer-totalPlanned`}
              />
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default PlanVoucherDemoView;
